import{_ as n,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"Datenschutzerklärung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy.md","filePath":"de/guide/privacy.md","lastUpdated":1793163976000}'),a={name:"de/guide/privacy.md"};function l(s,e,o,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="datenschutzerklarung" tabindex="-1">Datenschutzerklärung <a class="header-anchor" href="#datenschutzerklarung" aria-label="Permalink to &quot;Datenschutzerklärung&quot;">​</a></h1><p>NueZip ist als vollständig offline-first ausgelegte Anwendung konzipiert. Ihre Privatsphäre hat Priorität.</p><h2 id="nur-lokal-design" tabindex="-1">Nur-lokal-Design <a class="header-anchor" href="#nur-lokal-design" aria-label="Permalink to &quot;Nur-lokal-Design&quot;">​</a></h2><ul><li>Alle Archivvorgänge — Komprimierung, Extraktion, Konvertierung, Verschlüsselung — laufen vollständig auf Ihrem Mac.</li><li>NueZip lädt Ihre Dateien oder Daten nicht auf externe Server hoch.</li><li>Für die Nutzung der App ist kein Konto oder keine Registrierung erforderlich.</li><li>Für den normalen Betrieb ist keine Internetverbindung erforderlich.</li></ul><h2 id="was-wir-nicht-sammeln" tabindex="-1">Was wir nicht sammeln <a class="header-anchor" href="#was-wir-nicht-sammeln" aria-label="Permalink to &quot;Was wir nicht sammeln&quot;">​</a></h2><ul><li>Wir erfassen keine Ihrer Dateien, Dokumente oder Archivinhalte.</li><li>Wir verfolgen Ihre Aktivitäten, Ihr Surfverhalten oder Nutzungsmuster nicht.</li><li>Wir senden keine Dateimetadaten oder persönlichen Informationen an externe Server.</li><li>Wir enthalten keine Analyses-, Werbe- oder Tracking-SDKs von Drittanbietern.</li><li>Wir verfügen über kein Telemetriesystem.</li></ul><h2 id="welche-daten-lokal-gespeichert-werden" tabindex="-1">Welche Daten lokal gespeichert werden <a class="header-anchor" href="#welche-daten-lokal-gespeichert-werden" aria-label="Permalink to &quot;Welche Daten lokal gespeichert werden&quot;">​</a></h2><p>Folgende Daten werden nur auf Ihrem Gerät gespeichert:</p><ul><li><strong>App-Einstellungen</strong>: Theme, Sprachpräferenz, Komprimierungspräferenzen</li><li><strong>Lizenzschlüssel</strong>: Bei Kauf (sicher im lokalen Schlüsselbund gespeichert)</li><li><strong>Liste zuletzt geöffneter Dateien</strong>: Kürzlich geöffnete Archive für schnellen Zugriff</li><li><strong>Passworteinträge</strong>: Im lokalen Schlüsselbund gespeichert, wenn Sie sie zu speichern wählen</li><li><strong>Protokolle</strong>: Debug-Protokolle zur Fehlerbehebung (jederzeit löschbar)</li></ul><h2 id="vom-der-app-genutzte-berechtigungen" tabindex="-1">Vom der App genutzte Berechtigungen <a class="header-anchor" href="#vom-der-app-genutzte-berechtigungen" aria-label="Permalink to &quot;Vom der App genutzte Berechtigungen&quot;">​</a></h2><ul><li><strong>Dateien und Ordner</strong>: Erforderlich, um Archivdateien zu lesen und Inhalte zu extrahieren.</li><li><strong>Finder-Erweiterung</strong>: Optional, fügt Kontextmenüeinträge per Rechtsklick im Finder hinzu.</li><li><strong>Benachrichtigungen</strong>: Optional, für Abschlussbenachrichtigungen bei zeitaufwändigen Aufgaben.</li></ul><p>Sie können diese Berechtigungen jederzeit in <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> verwalten.</p><h2 id="in-app-kaufe-lizenz" tabindex="-1">In-App-Käufe / Lizenz <a class="header-anchor" href="#in-app-kaufe-lizenz" aria-label="Permalink to &quot;In-App-Käufe / Lizenz&quot;">​</a></h2><p>Lizenzkäufe werden von Apple über den Mac App Store abgewickelt. NueZip erhält oder speichert keine Ihrer Zahlungsinformationen. Lizenzbelege werden lokal gespeichert, um den Besitz zu verifizieren.</p><h2 id="dienste-von-drittanbietern" tabindex="-1">Dienste von Drittanbietern <a class="header-anchor" href="#dienste-von-drittanbietern" aria-label="Permalink to &quot;Dienste von Drittanbietern&quot;">​</a></h2><p>NueZip enthält keine Analyses-, Werbe- oder Tracking-Dienste von Drittanbietern. Die App ist vollständig eigenständig.</p><h2 id="datenschutzanfragen" tabindex="-1">Datenschutzanfragen <a class="header-anchor" href="#datenschutzanfragen" aria-label="Permalink to &quot;Datenschutzanfragen&quot;">​</a></h2><p>Da NueZip alle Daten lokal auf Ihrem Gerät speichert, halten wir keine persönlichen Daten auf unseren Servern vor. Wenn Sie Fragen zum Datenschutz haben, kontaktieren Sie uns bitte.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Für Datenschutzfragen öffnen Sie ein Issue unter <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> oder schreiben Sie uns eine E-Mail.</p>',20)])])}const p=n(a,[["render",l]]);export{g as __pageData,p as default};
